import { basename } from 'node:path';

const DEFAULT_PROGRAM_NAME = 'test9.mjs';

export function getProgramName(argv) {
  if (!Array.isArray(argv) || argv.length < 2) {
    return DEFAULT_PROGRAM_NAME;
  }

  const scriptPath = typeof argv[1] === 'string' ? argv[1] : '';
  return scriptPath.length > 0 ? basename(scriptPath) : DEFAULT_PROGRAM_NAME;
}

export function formatHelp(programName) {
  return `usage: ${programName} [-h] --a A\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;
}

export function formatError(programName, message) {
  return `usage: ${programName} [-h] --a A\n${programName}: error: ${message}\n`;
}

